package com.sivion.api.finance.service;
import com.sivion.api.finance.domain.*; import com.sivion.api.finance.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Service public class FinanceService {private static final long T=1L; private final InvoiceRepository invoices; private final PaymentRepository payments; private final ExpenseRepository expenses; public FinanceService(InvoiceRepository i,PaymentRepository p,ExpenseRepository e){invoices=i;payments=p;expenses=e;} public List<InvoiceView> invoices(){return invoices.findByTenantIdOrderByInvoiceDateDesc(T).stream().map(i->new InvoiceView(i.getId(),i.getInvoiceNumber(),i.getCustomerId(),i.getAmount(),i.getStatus(),i.getInvoiceDate())).toList();} @Transactional public InvoiceView invoice(InvoiceRequest r){if(r.customerId()==null||r.amount()==null||r.amount().signum()<0)throw new IllegalArgumentException("Customer and valid amount are required");Invoice i=new Invoice();i.setTenantId(T);i.setInvoiceNumber("INV-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());i.setCustomerId(r.customerId());i.setAmount(r.amount());return map(invoices.save(i));} public List<PaymentView> payments(){return payments.findByTenantIdOrderByPaidAtDesc(T).stream().map(p->new PaymentView(p.getId(),p.getPaymentNumber(),p.getInvoiceId(),p.getAmount(),p.getMethod(),p.getPaidAt())).toList();} @Transactional public PaymentView payment(PaymentRequest r){Invoice i=invoices.findByIdAndTenantId(r.invoiceId(),T).orElseThrow(()->new NoSuchElementException("Invoice not found"));if(r.amount()==null||r.amount().signum()<=0)throw new IllegalArgumentException("Payment amount must be greater than zero");Payment p=new Payment();p.setTenantId(T);p.setPaymentNumber("PAY-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());p.setInvoiceId(i.getId());p.setAmount(r.amount());p.setMethod(r.method()==null?"OTHER":r.method());return map(payments.save(p));} public List<ExpenseView> expenses(){return expenses.findByTenantIdOrderByExpenseDateDesc(T).stream().map(e->new ExpenseView(e.getId(),e.getExpenseNumber(),e.getCategory(),e.getDescription(),e.getAmount(),e.getStatus(),e.getExpenseDate())).toList();} @Transactional public ExpenseView expense(ExpenseRequest r){if(r.amount()==null||r.amount().signum()<=0)throw new IllegalArgumentException("Expense amount must be greater than zero");Expense e=new Expense();e.setTenantId(T);e.setExpenseNumber("EXP-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());e.setCategory(r.category());e.setDescription(r.description());e.setAmount(r.amount());return map(expenses.save(e));} private InvoiceView map(Invoice x){return new InvoiceView(x.getId(),x.getInvoiceNumber(),x.getCustomerId(),x.getAmount(),x.getStatus(),x.getInvoiceDate());} private PaymentView map(Payment x){return new PaymentView(x.getId(),x.getPaymentNumber(),x.getInvoiceId(),x.getAmount(),x.getMethod(),x.getPaidAt());} private ExpenseView map(Expense x){return new ExpenseView(x.getId(),x.getExpenseNumber(),x.getCategory(),x.getDescription(),x.getAmount(),x.getStatus(),x.getExpenseDate());} public record InvoiceRequest(Long customerId,BigDecimal amount){} public record InvoiceView(Long id,String invoiceNumber,Long customerId,BigDecimal amount,String status,Instant invoiceDate){} public record PaymentRequest(Long invoiceId,BigDecimal amount,String method){} public record PaymentView(Long id,String paymentNumber,Long invoiceId,BigDecimal amount,String method,Instant paidAt){} public record ExpenseRequest(String category,String description,BigDecimal amount){} public record ExpenseView(Long id,String expenseNumber,String category,String description,BigDecimal amount,String status,Instant expenseDate){} }
